#include <iostream>
#include <cstdio>
#include <algorithm>
using namespace std;

#define MAXN 1010
#define MAXM 11
#define ll long long

ll f[MAXN][MAXM][MAXN];
ll ways[MAXN][MAXM];
ll ine[MAXM];
int n, d;
ll mod;

ll mulMod(ll a, ll b) {
    return (ll)((__int128)a * b % mod);
}

ll addMod(ll a, ll b) {
    return (ll)(((__int128)a + b) % mod);
}

ll C(ll x, int y) {
    ll result = 1 % mod;
    for (int i = 1; i <= y; ++i) {
        ll factor = (x - y + i) % mod;
        if (factor < 0) factor += mod;
        result = mulMod(result, factor);
    }
    for (int i = 1; i <= y; ++i)
        result = mulMod(result, ine[i]);
    return result;
}

int main() {
    scanf("%d%d%lld", &n, &d, &mod);

    if (n <= 2) {
        printf("1\n");
        return 0;
    }

    ine[0] = ine[1] = 1 % mod;
    for (int i = 2; i <= 10; ++i)
        ine[i] = mulMod(mod - mod / i, ine[mod % i]);

    for (int i = 0; i <= n; ++i) {
        f[1][0][i] = 1 % mod;
        f[1][d - 1][i] = 1 % mod;
    }

    for (int l = 0; l <= d; ++l)
        ways[1][l] = C(f[1][d - 1][0] + l - 1, l);

    for (int i = 2; i <= n; ++i) {
        for (int j = 1; j <= d && j < i; ++j) {
            for (int k = 1; k < i; ++k) {
                f[i][j][k] = f[i][j][k - 1];
                for (int l = 1; l <= j && l * k < i; ++l) {
                    ll value = mulMod(f[i - l * k][j - l][k - 1],
                                      ways[k][l]);
                    f[i][j][k] = addMod(f[i][j][k], value);
                }
            }
        }

        for (int l = 0; l <= d; ++l)
            ways[i][l] = C(f[i][d - 1][i - 1] + l - 1, l);
    }

    ll ans;
    if (n & 1) {
        ans = f[n][d][n / 2];
    } else {
        ans = addMod(f[n][d][n / 2 - 1],
                     C(f[n / 2][d - 1][n / 2 - 1] + 1, 2));
    }

    printf("%lld\n", ans);
    return 0;
}

#include <cstdio>
#include <algorithm>
using namespace std;

#define MAXN 1010
#define MAXM 11

using ll = long long;
using i128 = __int128_t;

ll f[MAXN][MAXM][MAXN];
ll inv[MAXM];
ll ways[MAXN][MAXM];

int n, d;
ll mod;

inline ll mulMod(ll a, ll b) {
    return static_cast<ll>((i128)a * b % mod);
}

int main() {
    scanf("%d%d%lld", &n, &d, &mod);

    if (n <= 2) {
        printf("1\n");
        return 0;
    }

    inv[0] = inv[1] = 1;
    for (int i = 2; i <= 10; ++i) {
        inv[i] = mulMod(mod - mod / i, inv[mod % i]);
    }

    for (int k = 0; k <= n; ++k) {
        f[1][0][k] = 1;
        f[1][d - 1][k] = 1;
    }

    ways[1][0] = 1;
    for (int l = 1; l <= d; ++l) {
        ll factor = (f[1][d - 1][0] + l - 1) % mod;
        ways[1][l] = mulMod(mulMod(ways[1][l - 1], factor), inv[l]);
    }

    for (int i = 2; i <= n; ++i) {
        for (int j = 1; j <= d && j < i; ++j) {
            for (int k = 1; k < i; ++k) {
                ll value = f[i][j][k - 1];
                int limit = min(j, (i - 1) / k);

                for (int l = 1; l <= limit; ++l) {
                    value += mulMod(f[i - l * k][j - l][k - 1],
                                    ways[k][l]);
                    if (value >= mod)
                        value -= mod;
                }

                f[i][j][k] = value;
            }

            for (int k = i; k <= n; ++k)
                f[i][j][k] = f[i][j][k - 1];
        }

        ways[i][0] = 1;
        ll count = f[i][d - 1][i - 1];
        for (int l = 1; l <= d; ++l) {
            ll factor = static_cast<ll>(((i128)count + l - 1) % mod);
            ways[i][l] = mulMod(mulMod(ways[i][l - 1], factor), inv[l]);
        }
    }

    ll answer;
    if (n & 1) {
        answer = f[n][d][n / 2];
    } else {
        answer = f[n][d][n / 2 - 1] + ways[n / 2][2];
        if (answer >= mod)
            answer -= mod;
    }

    printf("%lld\n", answer);
    return 0;
}

